"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[785],{785:e=>{e.exports=JSON.parse('{"topic":{"id":"classes-objects-deep","title":"Classes & Objects (Deep Dive)","overviewSimple":"Imagine a blueprint for a toy car. The blueprint isn\u2019t a car, but you can create many toy cars from it. In Java, a class is the blueprint, and objects are the actual cars you create.","overviewTechnical":["A class is a template defining fields, methods, constructors, and behavior.","Objects are instances of a class stored in heap memory.","Accessing members requires dot notation (object.method()).","Constructors initialize object state.","Java supports encapsulation using private fields and public getters/setters."],"story":"Sara drew a sketch of a house. Using the sketch, she built many houses. The sketch never changed \u2014 only the houses did. That sketch is just like a Java class.","realWorldAnalogy":"A class is like a recipe; objects are the actual dishes prepared using the recipe.","keyPoints":["Class = blueprint, Object = instance","Constructors initialize data","Objects stored in heap memory","Encapsulation hides data"],"exampleSimple":"class Dog {\\n    String name;\\n}\\nDog d = new Dog();\\nd.name = \\"Rocky\\";","exampleTechnical":["public class Car {\\n    private String brand;\\n    private int speed;\\n\\n    public Car(String brand, int speed) {\\n        this.brand = brand;\\n        this.speed = speed;\\n    }\\n\\n    public void accelerate() {\\n        speed += 10;\\n    }\\n\\n    public int getSpeed() {\\n        return speed;\\n    }\\n\\n    public static void main(String[] args) {\\n        Car c = new Car(\\"BMW\\", 50);\\n        c.accelerate();\\n        System.out.println(c.getSpeed());\\n    }\\n}","class Student {\\n    private int id;\\n    private String name;\\n\\n    public Student(int id, String name) {\\n        this.id = id;\\n        this.name = name;\\n    }\\n\\n    public void display() {\\n        System.out.println(id + \\" - \\" + name);\\n    }\\n}\\n\\npublic class Main {\\n    public static void main(String[] args) {\\n        Student s = new Student(1, \\"Amit\\");\\n        s.display();\\n    }\\n}"],"extraNotes":["\u2018this\u2019 refers to the current object.","Classes may contain nested classes.","Multiple objects can share static members."],"bestPracticesSimple":["Use clear class names","Give objects meaningful data"],"bestPracticesAdvanced":["Keep fields private and expose minimal getters/setters","Use composition over inheritance when possible","Follow single-responsibility principle"]}}')}}]);